/// <summary>
/// This class handles the dialog for modification of Excise Register Entry records
/// </summary>
class METExciseRegisterEntryModifyDialog
{
    protected Dialog        dialog;
    protected DialogField   dlgLodgement, dlgDutyReceived, dlgTransactionQty, dlgQty,dlgPermisionNumber,dlgTIUV,dlgAvailableQty,dlgReasonCode;

    private METLodgement                metLodgement;
    private METDutyRateReceived         metDutyReceived;
    private Qty                         transactionQty, qty, availableQty;
    private METPermissionNumber         permissionNumber;
    private METTransportInsurance       tiuv;
    private InventCountingReasonCodeId  reasonCode;
    
}

Method.Source:
    public static void main(Args _args)
    {
        METExciseRegisterEntryModifyDialog  dialogExciseRegisterEntry;
        METExciseRegisterEntry              metExciseRegisterEntry;
        FormDataSource                      metExciseRegisterEntry_ds;

        //Check if the Args.Record() has the same TableID as the Table Buffer(custTable).
        if  (_args.record().TableId == tableNum(METExciseRegisterEntry))
        {
            //Assign the args records to table buffer and then pass it to salesLine_ds(FormDataSource)
            metExciseRegisterEntry      = _args.record();
            metExciseRegisterEntry_ds   = FormDataUtil::getFormDataSource(metExciseRegisterEntry);  //metExciseRegisterEntry.dataSource();
 
            //Call Method which will be used to create the Dialog
            dialogExciseRegisterEntry = new METExciseRegisterEntryModifyDialog();

            dialogExciseRegisterEntry.updateExciseRegisterEntries(metExciseRegisterEntry_ds,_args);
        }
    }

    private void updateExciseRegisterEntries(FormDataSource metExciseRegisterEntry_ds, Args _args)
    {
        //The method createFromCaller from MultiSelectionHelper has FormRun as parameter so we need to assign Args.Caller() to FormRun
        FormRun formCaller  = _args.caller();
 
        //This method will help to get only the marked records from the Grid
        MultiSelectionHelper multiSelectionHelper  = MultiSelectionHelper::createFromCaller(formCaller);

        dialog = this.dialog();

        //The code will only be executed if the user click on Yes
        if (dialog.run())
        {
            if(this.getFromDialog())
            {
                //Create the Query to filter using RecId
                multiSelectionHelper.createQueryRanges(metExciseRegisterEntry_ds.queryBuildDataSource(), fieldStr(METExciseRegisterEntry, RecId));

                //Obtains the first query result and then assign it to table buffer
                METExciseRegisterEntry  metExciseRegisterEntry = multiSelectionHelper.getFirst();
 
                //True if metExciseRegisterEntry contains RecId
                while (metExciseRegisterEntry)
                {

                    //only modify if available Qty matches quantity i.e nothing has been consumed
                    info(StrFmt('RecId %1 ItemId - %2 , LodgementId - %3, New ID - %4', metExciseRegisterEntry.RecId,metExciseRegisterEntry.ItemId,metExciseRegisterEntry.Lodgement,metLodgement));
 
                    //Gets next record
                    metExciseRegisterEntry = multiSelectionHelper.getNext();
                }
            }
        }
    }

    /// <summary>
    /// Builds the dialog.
    /// </summary>
    /// <returns>The dialog</returns>
    protected Dialog dialog()
    {
        //Create a Dialog with title
        dialog = new Dialog('Modify Excise Register Entries' );

        dlgLodgement        = dialog.addField(extendedTypeStr(METLodgement),'LodgementId');
        dlgLodgement.fieldControl().mandatory(true);

        dlgDutyReceived    = dialog.addField(extendedTypeStr(METDutyRateReceived),'Duty Rate Received');
        dlgTransactionQty  = dialog.addField(extendedTypeStr(Qty),'Transaction Quantity');
        dlgQty             = dialog.addField(extendedTypeStr(Qty),'Quantity');
        dlgPermisionNumber = dialog.addField(extendedTypeStr(METPermissionNumber),'Permission Number');
        dlgTIUV            = dialog.addField(extendedTypeStr(METTransportInsurance),'TIUV');
        dlgAvailableQty    = dialog.addField(extendedTypeStr(Qty),'Available Quantity');
        dlgReasonCode      = dialog.addField(extendedTypeStr(InventCountingReasonCodeId),'Reason Code');

        //Create a "Label" do Dialog
        dialog.addText( 'Do you wish to proceed?');

        dialog.formBuildDesign().dialogSize(0);

        return dialog;
    }

    /// <summary>
    /// Retrieves values from the dialog after it is completed.
    /// </summary>
    /// <returns>true if values are retrieved successfully; otherwise, false.</returns>
    protected boolean getFromDialog()
    {
        boolean ret = true;

        metLodgement        = dlgLodgement.value();
        metDutyReceived     = dlgDutyReceived.value();
        transactionQty      = dlgTransactionQty.value();
        qty                 = dlgQty.value();
        permissionNumber    = dlgPermisionNumber.value();
        tiuv                = dlgTIUV.value();
        availableQty        = dlgAvailableQty.value();
        reasonCode          = dlgReasonCode.value();

        //do any validation here
        if(metLodgement == '')
        {
            ret = checkFailed('Lodgement Number is mandatory');
        }

        return ret;
    }

public static METExciseRegisterEntryModifyDialog construct()
{
    return new METExciseRegisterEntryModifyDialog();
}
